package chat.oldy;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;

/** Offline documents and explicit, separately scoped consent; no global access to private chats. */
final class LegalCenter {
 static final String VERSION="2026-09-10.1";
 static String tr(String ru,String en){return I18n.language().equals("en")?en:ru;}
 static JSONObject documents(MainActivity a)throws Exception{try(InputStream in=a.getAssets().open("legal_texts.json")){return new JSONObject(Api.read(in,60000)).getJSONObject(I18n.language().equals("en")?"en":"ru");}}
 static void document(MainActivity a,String key){try{JSONObject doc=documents(a).getJSONObject(key);LinearLayout body=a.col();a.pad(body,18);JSONArray paragraphs=doc.getJSONArray("body");for(int i=0;i<paragraphs.length();i++){TextView text=a.label(paragraphs.getString(i),14,a.TEXT);text.setTextIsSelectable(true);text.setLineSpacing(a.dp(4),1);body.addView(text);a.space(body,14);}ScrollView scroll=new ScrollView(a);scroll.addView(body);a.dialog().setTitle(doc.getString("title")).setView(scroll).setPositiveButton(I18n.t("Закрыть"),null).show();}catch(Exception e){a.error(Api.message(e));}}
 static CheckBox signup(MainActivity a,LinearLayout parent){CheckBox agree=new CheckBox(a);agree.setText(tr("Принимаю условия и правила сообщества; ознакомился с политикой конфиденциальности","I accept the terms and community rules and have read the privacy policy"));agree.setTextSize(13);agree.setTextColor(a.TEXT);parent.addView(agree);links(a,parent);return agree;}
 static void links(MainActivity a,LinearLayout parent){try{JSONObject docs=documents(a);for(String key:new String[]{"privacy","terms","community"}){TextView link=a.button(docs.getJSONObject(key).getString("title"),false,()->document(a,key));parent.addView(link);a.space(parent,6);}}catch(Exception ignored){}}
 static void show(MainActivity a){LinearLayout b=SettingsHome.page(a,tr("Правила и поддержка","Rules and support"),"legal");links(a,b);b.addView(a.button(tr("Удаление данных: как это работает","How account deletion works"),false,()->document(a,"delete")));a.space(b,12);TextView operator=a.label(tr("Загружаем контакты оператора…","Loading operator contact details…"),13,a.MUTED);b.addView(operator);
  a.task(()->{JSONObject info=a.api.call("/legal/info",null,"");a.runOnUiThread(()->{if(a.isDestroyed())return;operator.setText(info.optBoolean("configured")?info.optString("operator")+"\n"+info.optString("support_email")+"\n"+tr("Безопасность детей: ","Child safety: ")+info.optString("child_safety_email"):tr("Владелец пока не указал контакты поддержки. Жалобы внутри приложения доступны.","The operator has not configured public support contacts yet. In-app reports are available."));if(info.optString("support_email").matches("[^\\s@]+@[^\\s@]+"))operator.setOnClickListener(v->{try{a.startActivity(new Intent(Intent.ACTION_SENDTO,Uri.fromParts("mailto",info.optString("support_email"),null)));}catch(Exception e){a.error(info.optString("support_email"));}});});});
  b.addView(a.button(tr("Лицензии компонентов","Open-source licenses"),false,()->licenses(a)));if(!a.vault.token().isEmpty()){a.space(b,16);b.addView(a.button(tr("Мои жалобы","My reports"),false,()->reports(a,false)));if(a.vault.moderator()){a.space(b,8);b.addView(a.button(tr("Очередь модерации","Moderation inbox"),true,()->reports(a,true)));}a.space(b,8);b.addView(a.button(tr("Принять актуальные правила","Accept current rules"),false,()->ask(a)));}
 }
 static void check(MainActivity a){final Vault owner=a.vault;a.work.execute(()->{try{JSONObject status=a.api.call("/legal/status",null,owner.token());synchronized(owner){owner.data.put("accepted_policy",status.optString("accepted_version"));owner.save();}a.runOnUiThread(()->{if(a.vault==owner&&!a.isFinishing()&&!VERSION.equals(status.optString("accepted_version")))ask(a);});}catch(Exception ignored){}});}
 static void ask(MainActivity a){if(a.isFinishing()||a.vault.token().isEmpty()||a.policyDialog)return;a.policyDialog=true;final Vault owner=a.vault;LinearLayout b=a.col();a.pad(b,16);CheckBox consent=signup(a,b);ScrollView scroll=new ScrollView(a);scroll.addView(b);AlertDialog d=a.dialog().setTitle(tr("Правила Oldi Chat","Oldi Chat rules")).setView(scroll).setNegativeButton(tr("Позже","Later"),null).setPositiveButton(tr("Принять","Accept"),null).create();d.setOnDismissListener(x->a.policyDialog=false);d.setOnShowListener(x->{Button ok=d.getButton(-1);ok.setEnabled(false);consent.setOnCheckedChangeListener((v,checked)->ok.setEnabled(checked));ok.setOnClickListener(v->{ok.setEnabled(false);a.task(()->{try{a.api.call("/legal/accept",new JSONObject().put("version",VERSION).put("accept",true),owner.token());synchronized(owner){owner.data.put("accepted_policy",VERSION);owner.save();}a.runOnUiThread(d::dismiss);}finally{a.runOnUiThread(()->ok.setEnabled(true));}});});});d.show();}
 static void report(MainActivity a,String target,JSONObject message){LinearLayout b=a.col();a.pad(b,16);String[] ids={"spam","harassment","violence","sexual_content","child_safety","impersonation","copyright","other"},labels=I18n.language().equals("en")?new String[]{"Spam","Harassment","Violence","Sexual content","Child safety","Impersonation","Copyright","Other"}:new String[]{"Спам","Травля","Насилие","Сексуальный контент","Безопасность детей","Выдаёт себя за другого","Авторские права","Другое"};Spinner reason=new Spinner(a);reason.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,labels));b.addView(reason);String excerpt=message==null?"":message.optString("text");if(excerpt.length()>4000)excerpt=excerpt.substring(0,4000);final String selected=excerpt;TextView preview=a.label("@"+target+(selected.isEmpty()?"":"\n"+selected),14,a.TEXT);preview.setTextIsSelectable(true);b.addView(preview);EditText detail=a.field(b,tr("Пояснение (необязательно)","Explanation (optional)"),false);detail.setSingleLine(false);detail.setMaxLines(4);detail.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2000)});CheckBox consent=new CheckBox(a);consent.setText(tr("Передать модератору мой @ник, этого автора, причину и показанный фрагмент с пояснением","Share my handle, this author, reason and the displayed excerpt/explanation with the moderator"));consent.setTextColor(a.TEXT);b.addView(consent);a.paragraph(b,tr("Полная переписка и медиа не прикладываются. Для опасного материала укажите сообщение, не пересылая его.","The full chat and media are not attached. Identify harmful material without re-sharing it."));ScrollView scroll=new ScrollView(a);scroll.addView(b);AlertDialog d=a.dialog().setTitle(tr("Пожаловаться","Report")).setView(scroll).setNegativeButton(I18n.t("Отмена"),null).setPositiveButton(tr("Отправить жалобу","Send report"),null).create();d.setOnShowListener(x->{Button send=d.getButton(-1);send.setEnabled(false);consent.setOnCheckedChangeListener((v,on)->send.setEnabled(on));send.setOnClickListener(v->{final int reasonId=reason.getSelectedItemPosition();final String explanation=detail.getText().toString();send.setEnabled(false);a.task(()->{try{String peer=message==null?"":message.optString("peer");JSONObject payload=new JSONObject().put("target",target).put("mid",message==null?"":message.optString("id")).put("room",Conversation.community(peer)?Conversation.room(peer):"").put("reason",ids[reasonId]).put("excerpt",selected).put("detail",explanation).put("share_consent",true);a.api.call("/reports",payload,a.vault.token());a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,tr("Жалоба отправлена модератору","Report sent to the moderator"),Toast.LENGTH_LONG).show();});}finally{a.runOnUiThread(()->send.setEnabled(true));}});});});d.show();}
 static void reports(MainActivity a,boolean moderation){LinearLayout b=SettingsHome.page(a,tr(moderation?"Модерация":"Мои жалобы",moderation?"Moderation":"My reports"),"legal");TextView status=a.label(tr("Загружаем…","Loading…"),14,a.MUTED);b.addView(status);a.task(()->{JSONArray rows=a.api.call(moderation?"/moderation/reports":"/reports/mine",null,a.vault.token()).getJSONArray("reports");a.runOnUiThread(()->{status.setText(rows.length()==0?tr("Жалоб пока нет","No reports yet"):tr("Обращений: ","Reports: ")+rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);String title=row.optString("reason")+" · "+row.optString("status");b.addView(a.button(title,false,()->{if(moderation)review(a,row);else a.error(row.optString("resolution",title));}));a.space(b,8);}});});}
 static void review(MainActivity a,JSONObject r){LinearLayout b=a.col();a.pad(b,16);TextView text=a.label(tr("Автор: @","Author: @")+r.optString("target")+"\n"+r.optString("reason")+"\n\n"+r.optString("excerpt")+"\n"+r.optString("detail"),14,a.TEXT);text.setTextIsSelectable(true);b.addView(text);a.paragraph(b,tr("Фрагмент предоставлен заявителем. Проверьте факты перед решением. Жалобы о безопасности детей требуют приоритетной реакции и действий по закону.","The reporter supplied this excerpt. Verify facts before action. Child safety reports require priority review and action under applicable law."));String[] actions={"remove_message","restrict_user","restore_user","dismiss","resolve"},labels=I18n.language().equals("en")?new String[]{"Remove message","Restrict publishing","Restore publishing","Dismiss report","Mark resolved"}:new String[]{"Удалить сообщение","Ограничить публикации","Вернуть публикации","Отклонить жалобу","Отметить рассмотренной"};for(int i=0;i<actions.length;i++){final String action=actions[i],label=labels[i];if(action.equals("remove_message")&&r.optString("mid").isEmpty())continue;b.addView(a.button(label,false,()->{EditText note=new EditText(a);note.setHint(tr("Причина решения","Decision reason"));a.dialog().setTitle(label+"?").setView(note).setNegativeButton(I18n.t("Отмена"),null).setPositiveButton(tr("Подтвердить","Confirm"),(d,w)->{String why=note.getText().toString();a.task(()->{a.api.call("/moderation/action",new JSONObject().put("id",r.optString("id")).put("action",action).put("note",why),a.vault.token());a.runOnUiThread(()->reports(a,true));});}).show();}));a.space(b,6);}a.sheet(tr("Рассмотреть жалобу","Review report"),b);}
 static void licenses(MainActivity a){try{LinearLayout b=a.col();a.pad(b,16);String[] files=a.getAssets().list("third-party");if(files!=null)for(String file:files){try(InputStream in=a.getAssets().open("third-party/"+file)){TextView text=a.label(file+"\n\n"+Api.read(in,80000),12,a.TEXT);text.setTextIsSelectable(true);b.addView(text);a.space(b,20);}catch(IOException directory){}}ScrollView scroll=new ScrollView(a);scroll.addView(b);a.dialog().setTitle(tr("Открытые лицензии","Open-source licenses")).setView(scroll).setPositiveButton(I18n.t("Закрыть"),null).show();}catch(Exception e){a.error(Api.message(e));}}
 static void deleteAccount(MainActivity a){final Vault owner=a.vault;LinearLayout b=a.col();a.pad(b,16);a.paragraph(b,tr("Будут удалены аккаунт, почта, профиль, серверная история и созданные тобой каналы и группы. Собеседники сохранят свои аккаунты. Копии у получателей могут остаться. Действие необратимо.","This permanently deletes your account, email, profile, server history and communities you created. Other people's accounts remain; recipient copies may remain."));b.addView(a.button(tr("Подробнее об удалении","Deletion details"),false,()->document(a,"delete")));EditText name=a.field(b,tr("Введи ник без @","Enter your handle without @"),false);AlertDialog d=a.dialog().setTitle(tr("Удалить аккаунт?","Delete account?")).setView(b).setNegativeButton(I18n.t("Отмена"),null).setPositiveButton(tr("Удалить навсегда","Delete permanently"),null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(!name.getText().toString().equals(owner.nick())){name.setError(tr("Ник не совпадает","Handle does not match"));return;}d.getButton(-1).setEnabled(false);a.task(()->{try{a.api.call("/account/delete",new JSONObject().put("confirm",owner.nick()),owner.token());a.runOnUiThread(()->{d.dismiss();eraseLocal(a,owner);});}finally{a.runOnUiThread(()->d.getButton(-1).setEnabled(true));}});}));d.show();}
 static void eraseLocal(MainActivity a,Vault owner){try{SpeechNotes.cancel();if(LiveCall.current!=null)LiveCall.current.end(I18n.t("Звонок завершён"),true);CreatorVideo.cancel=true;if(ChatService.instance!=null)ChatService.instance.running=false;a.stopService(new Intent(a,ChatService.class));a.stopService(new Intent(a,LocalTunnelService.class));owner.erase();Vault empty=Vault.guest(a);ChatService.shared=empty;a.vault=empty;a.mediaCache.evictAll();a.chat="";a.getSystemService(NotificationManager.class).cancelAll();a.auth(false);Toast.makeText(a,tr("Аккаунт удалён","Account deleted"),Toast.LENGTH_LONG).show();}catch(Exception e){a.error(Api.message(e));}}
}
